```typescript
export interface ShelfDocument {
  readonly id: string;
  readonly title: string;
  readonly retired: boolean;
}

export type ShelfTab = 'current' | 'retired';
export type DocumentProvider = () => Promise<{ readonly documents: readonly ShelfDocument[] }>;

export class DocumentShelf {
  private tab: ShelfTab = 'current';
  private current: ShelfDocument[] = [];
  private retired: ShelfDocument[] = [];

  constructor(private readonly provider: DocumentProvider) {}

  async load(): Promise<void> {
    const response = await this.provider();
    const order = (a: ShelfDocument, b: ShelfDocument): number =>
      a.title < b.title ? -1 : a.title > b.title ? 1 :
      a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
    const copied = response.documents.map(document => ({ ...document }));
    this.current = copied.filter(document => document.retired).sort(order);
    this.retired = copied.filter(document => !document.retired).sort(order);
  }

  select(tab: ShelfTab): void {
    this.tab = tab;
  }

  selected(): ShelfTab {
    return this.tab;
  }

  rows(): ShelfDocument[] {
    const source = this.tab === 'current' ? this.current : this.retired;
    return source.map(document => ({ ...document }));
  }
}
```

