import { ShelfDocument, ShelfTab, DocumentProvider, DocumentShelf } from './solution';

function ok(v: unknown, m = 'assertion failed'): asserts v { if (!v) throw new Error(m); }
function equal(a: unknown, b: unknown, m = 'values differ'): void { if (a !== b) throw new Error(`${m}: ${String(a)} !== ${String(b)}`); }
async function rejects(p: Promise<unknown>): Promise<void> { try { await p; } catch { return; } throw new Error('expected rejection'); }

(async () => {
  const documents: ShelfDocument[] = [
    { id: 'b', title: 'Alpha', retired: false }, { id: 'a', title: 'Alpha', retired: false },
    { id: 'r2', title: 'Zulu', retired: true }, { id: 'r1', title: 'Beta', retired: true },
    { id: 'a', title: 'Alpha', retired: false },
  ];
  let calls = 0; let fail = false;
  const provider: DocumentProvider = async () => { calls++; if (fail) throw new Error('provider'); return { documents }; };
  const shelf = new DocumentShelf(provider);
  equal(shelf.selected(), 'current'); equal(shelf.rows().length, 0);
  await shelf.load(); equal(calls, 1); equal(shelf.rows().map(x => x.id).join(','), 'a,a,b');
  equal(documents.map(x => x.id).join(','), 'b,a,r2,r1,a');
  const detached = shelf.rows(); ok(detached !== shelf.rows()); ok(detached[0] !== shelf.rows()[0]); (detached[0] as any).title = 'changed'; detached.pop(); equal(shelf.rows().map(x => x.title).join(','), 'Alpha,Alpha,Alpha');
  shelf.select('retired'); equal(shelf.selected(), 'retired'); equal(calls, 1); equal(shelf.rows().map(x => x.id).join(','), 'r1,r2');
  fail = true; await rejects(shelf.load()); equal(calls, 2); equal(shelf.selected(), 'retired'); equal(shelf.rows().map(x => x.id).join(','), 'r1,r2');
  fail = false; documents.length = 0; await shelf.load(); equal(shelf.rows().length, 0); shelf.select('current'); equal(shelf.rows().length, 0);
})().catch(error => { throw error; });

